=== FILE: axil_timer.v ===
`timescale 1ns / 1ps
// -----------------------------------------------------------------------------
// axil_timer
//
// 32-bit down-counting timer with one-shot and periodic modes and a level
// interrupt, behind an AXI4-Lite subordinate port.
//
// Traceability:
//   requirement     : req-2b2b91a584 (AXI4-Lite timer peripheral with interrupt)
//   interface spec  : prj-f38ca11b11.interface-spec.a1 (interface_spec.md)
//   microarchitecture: prj-f38ca11b11.microarchitecture.a1 (microarchitecture.md)
//
// Register map (byte offsets):
//   0x0 CTRL   rw   bit0 EN, bit1 IE, bit2 MODE (0 one-shot, 1 periodic)
//   0x4 LOAD   rw   count length in cycles (0 counts as 1)
//   0x8 COUNT  ro   cycles left (write -> SLVERR, no effect)
//   0xC STATUS w1c  bit0 EXPIRED
// Any address that is unaligned or >= 0x10 is unmapped: writes change nothing
// and get SLVERR, reads return 0 with SLVERR.
// -----------------------------------------------------------------------------
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL   = 2'd0;
    localparam [1:0] IDX_LOAD   = 2'd1;
    localparam [1:0] IDX_COUNT  = 2'd2;
    localparam [1:0] IDX_STATUS = 2'd3;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg                  w_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;

    reg                  bvalid_q;
    reg [1:0]            bresp_q;

    reg                  rvalid_q;
    reg [31:0]           rdata_q;
    reg [1:0]            rresp_q;

    reg                  en;
    reg                  ie;
    reg                  mode;
    reg                  expired;
    reg [31:0]           load;
    reg [31:0]           count;

    // ------------------------------------------------------------------
    // Write channels (microarchitecture section 1)
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held && !bvalid_q;
    assign s_axil_wready  = !w_held  && !bvalid_q;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;

    wire aw_hs    = s_axil_awvalid && s_axil_awready;
    wire w_hs     = s_axil_wvalid  && s_axil_wready;
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // Address decode (microarchitecture section 3)
    wire [ADDR_WIDTH-1:0] wr_addr_hi = wr_addr >> 4;
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) && (wr_addr_hi == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);

    wire wr_ctrl  = do_write && wr_mapped && (wr_idx == IDX_CTRL)   && wr_strb[0];
    wire wr_load  = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire wr_clear = do_write && wr_mapped && (wr_idx == IDX_STATUS) && wr_strb[0] && wr_data[0];

    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held   <= 1'b0;
            w_held    <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
        end else begin
            if (do_write) begin
                aw_held  <= 1'b0;
                w_held   <= 1'b0;
                bvalid_q <= 1'b1;
                bresp_q  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held   <= 1'b1;
                    aw_addr_q <= s_axil_awaddr;
                end
                if (w_hs) begin
                    w_held   <= 1'b1;
                    w_data_q <= s_axil_wdata;
                    w_strb_q <= s_axil_wstrb;
                end
                if (bvalid_q && s_axil_bready) begin
                    bvalid_q <= 1'b0;
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channels
    // ------------------------------------------------------------------
    assign s_axil_arready = !rvalid_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rdata   = rdata_q;
    assign s_axil_rresp   = rresp_q;

    wire ar_hs = s_axil_arvalid && s_axil_arready;

    wire [ADDR_WIDTH-1:0] rd_addr_hi = s_axil_araddr >> 4;
    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) && (rd_addr_hi == {ADDR_WIDTH{1'b0}});
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    reg [31:0] rd_value;
    always @(*) begin
        case (rd_idx)
            IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
            IDX_LOAD:   rd_value = load;
            IDX_COUNT:  rd_value = count;
            IDX_STATUS: rd_value = {31'd0, expired};
            default:    rd_value = 32'd0;
        endcase
    end

    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rdata_q  <= 32'd0;
            rresp_q  <= RESP_OKAY;
        end else if (ar_hs) begin
            rvalid_q <= 1'b1;
            rdata_q  <= rd_mapped ? rd_value : 32'd0;
            rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
        end else if (rvalid_q && s_axil_rready) begin
            rvalid_q <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Timer (microarchitecture section 2). Order inside the block gives the
    // specified priorities by last-assignment-wins:
    //   1. count step, 2. expired (clear, then set), 3. CTRL write, 4. LOAD.
    // ------------------------------------------------------------------
    wire count_end = en && (count <= 32'd1);

    always @(posedge aclk) begin
        if (!aresetn) begin
            en      <= 1'b0;
            ie      <= 1'b0;
            mode    <= 1'b0;
            expired <= 1'b0;
            load    <= 32'd0;
            count   <= 32'd0;
        end else begin
            // 1. count step
            if (en) begin
                if (count_end) begin
                    if (mode) begin
                        count <= load;
                    end else begin
                        count <= 32'd0;
                        en    <= 1'b0;
                    end
                end else begin
                    count <= count - 32'd1;
                end
            end

            // 2. expired: a count end beats a clear
            if (wr_clear) begin
                expired <= 1'b0;
            end
            if (count_end) begin
                expired <= 1'b1;
            end

            // 3. CTRL write wins for en and count
            if (wr_ctrl) begin
                en   <= wr_data[0];
                ie   <= wr_data[1];
                mode <= wr_data[2];
                if (wr_data[0]) begin
                    count <= load;
                end
            end

            // 4. LOAD byte merge
            if (wr_load) begin
                if (wr_strb[0]) load[7:0]   <= wr_data[7:0];
                if (wr_strb[1]) load[15:8]  <= wr_data[15:8];
                if (wr_strb[2]) load[23:16] <= wr_data[23:16];
                if (wr_strb[3]) load[31:24] <= wr_data[31:24];
            end
        end
    end

    assign irq = expired && ie;

    // ------------------------------------------------------------------
    // Design-intent assertions (read only by a formal flow)
    // ------------------------------------------------------------------
`ifdef FORMAL
    reg f_past_valid = 1'b0;
    always @(posedge aclk) begin
        f_past_valid <= 1'b1;
    end

    always @(posedge aclk) begin
        if (f_past_valid && !$past(aresetn)) begin
            assert(!bvalid_q);
            assert(!rvalid_q);
            assert(!aw_held);
            assert(!w_held);
            assert(!en);
            assert(!expired);
        end
        if (f_past_valid && $past(aresetn)) begin
            if ($past(bvalid_q && !s_axil_bready)) begin
                assert(bvalid_q);
                assert(bresp_q == $past(bresp_q));
            end
            if ($past(rvalid_q && !s_axil_rready)) begin
                assert(rvalid_q);
                assert(rdata_q == $past(rdata_q));
                assert(rresp_q == $past(rresp_q));
            end
        end
        assert(!(aw_held && w_held));
        assert(!(aw_held && bvalid_q));
        assert(!(w_held && bvalid_q));
        assert(irq == (expired && ie));
    end
`endif

endmodule
=== END FILE ===
=== FILE: axil_timer_tb.v ===
`timescale 1ns / 1ps
// -----------------------------------------------------------------------------
// axil_timer_tb: self-checking directed testbench for axil_timer.
// Traceability: interface spec prj-f38ca11b11.interface-spec.a1 section 8,
// microarchitecture prj-f38ca11b11.microarchitecture.a1 section 5.
//
// Two instances: dut8 (ADDR_WIDTH 8) and dut4 (ADDR_WIDTH 4). "sel" chooses
// which one sees bus traffic; the other's valids/readies are gated off.
// All stimulus changes and all sampling happen 2 ns after a rising edge;
// the edge counter "cycle" and the irq-rise monitor run 1 ns after it.
// -----------------------------------------------------------------------------

`define CHK(COND, MSG) begin if (COND) passed = passed + 1; else begin failed = failed + 1; $error("FAIL: %0s", MSG); end end
`define CHK_EQ(GOT, EXP, MSG) begin if ((GOT) === (EXP)) passed = passed + 1; else begin failed = failed + 1; $error("FAIL: %0s: got 0x%0h expected 0x%0h", MSG, (GOT), (EXP)); end end

module axil_timer_tb;

    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;
    localparam [1:0] OKAY     = 2'b00;
    localparam [1:0] SLVERR   = 2'b10;

    reg         clk     = 1'b0;
    reg         aresetn = 1'b0;
    reg         sel     = 1'b0;

    reg  [7:0]  awaddr  = 8'h00;
    reg         awvalid = 1'b0;
    reg  [31:0] wdata   = 32'h0;
    reg  [3:0]  wstrb   = 4'h0;
    reg         wvalid  = 1'b0;
    reg         bready  = 1'b0;
    reg  [7:0]  araddr  = 8'h00;
    reg         arvalid = 1'b0;
    reg         rready  = 1'b0;

    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr[3:0]),
        .s_axil_awvalid (awvalid & ~sel),
        .s_axil_awready (awready4),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid & ~sel),
        .s_axil_wready  (wready4),
        .s_axil_bresp   (bresp4),
        .s_axil_bvalid  (bvalid4),
        .s_axil_bready  (bready & ~sel),
        .s_axil_araddr  (araddr[3:0]),
        .s_axil_arvalid (arvalid & ~sel),
        .s_axil_arready (arready4),
        .s_axil_rdata   (rdata4),
        .s_axil_rresp   (rresp4),
        .s_axil_rvalid  (rvalid4),
        .s_axil_rready  (rready & ~sel),
        .irq            (irq4)
    );

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid & sel),
        .s_axil_awready (awready8),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid & sel),
        .s_axil_wready  (wready8),
        .s_axil_bresp   (bresp8),
        .s_axil_bvalid  (bvalid8),
        .s_axil_bready  (bready & sel),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid & sel),
        .s_axil_arready (arready8),
        .s_axil_rdata   (rdata8),
        .s_axil_rresp   (rresp8),
        .s_axil_rvalid  (rvalid8),
        .s_axil_rready  (rready & sel),
        .irq            (irq8)
    );

    wire        awready_m = sel ? awready8 : awready4;
    wire        wready_m  = sel ? wready8  : wready4;
    wire        bvalid_m  = sel ? bvalid8  : bvalid4;
    wire [1:0]  bresp_m   = sel ? bresp8   : bresp4;
    wire        arready_m = sel ? arready8 : arready4;
    wire        rvalid_m  = sel ? rvalid8  : rvalid4;
    wire [31:0] rdata_m   = sel ? rdata8   : rdata4;
    wire [1:0]  rresp_m   = sel ? rresp8   : rresp4;
    wire        irq_m     = sel ? irq8     : irq4;

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    integer cycle = 0;
    integer irq_rises = 0;
    integer irq_rise_cycle = -1;
    reg     irq_prev = 1'b0;
    reg [8*64-1:0] nonce = {(8*64){1'b0}};

    integer    wr_edge = 0;
    integer    rd_edge = 0;
    reg [31:0] rd_data = 32'd0;
    reg [1:0]  rd_resp = 2'b00;

    integer    before;
    integer    e0;
    integer    s0;
    integer    r0;
    reg [31:0] c1;

    // Edge counter and irq rise monitor (1 ns after each rising edge).
    initial begin
        forever begin
            @(posedge clk);
            #1;
            cycle = cycle + 1;
            if (irq_m && !irq_prev) begin
                irq_rises      = irq_rises + 1;
                irq_rise_cycle = cycle;
            end
            irq_prev = irq_m;
        end
    end

    // Watchdog
    initial begin
        #2000000;
        $error("FAIL: watchdog timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

    // ------------------------------------------------------------------
    // Bus tasks
    // ------------------------------------------------------------------
    task tick;
        begin
            @(posedge clk);
            #2;
        end
    endtask

    task ticks(input integer n);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) tick;
        end
    endtask

    task wait_until(input integer target);
        begin
            while (cycle < target) tick;
        end
    endtask

    task send_aw(input [7:0] a);
        reg ok;
        begin
            awaddr  = a;
            awvalid = 1'b1;
            while (awvalid) begin
                ok = awready_m;
                tick;
                if (ok) awvalid = 1'b0;
            end
        end
    endtask

    task send_w(input [31:0] d, input [3:0] s);
        reg ok;
        begin
            wdata  = d;
            wstrb  = s;
            wvalid = 1'b1;
            while (wvalid) begin
                ok = wready_m;
                tick;
                if (ok) wvalid = 1'b0;
            end
        end
    endtask

    task send_both(input [7:0] a, input [31:0] d, input [3:0] s);
        reg aok;
        reg wok;
        begin
            awaddr  = a;
            wdata   = d;
            wstrb   = s;
            awvalid = 1'b1;
            wvalid  = 1'b1;
            while (awvalid || wvalid) begin
                aok = awvalid && awready_m;
                wok = wvalid && wready_m;
                tick;
                if (aok) awvalid = 1'b0;
                if (wok) wvalid  = 1'b0;
            end
        end
    endtask

    task finish_b(input [7:0] a, input [1:0] er, input integer bdly);
        integer   i;
        reg [1:0] r;
        begin
            `CHK(bvalid_m === 1'b1, "BVALID high after the write completes")
            if (bresp_m === er) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("FAIL: write 0x%0h: BRESP %b expected %b", a, bresp_m, er);
            end
            r = bresp_m;
            for (i = 0; i < bdly; i = i + 1) begin
                tick;
                `CHK(bvalid_m === 1'b1, "BVALID held under backpressure")
                `CHK_EQ(bresp_m, r, "BRESP stable under backpressure")
                `CHK(!awready_m && !wready_m, "no write accepted while BVALID waits")
            end
            bready = 1'b1;
            tick;
            bready = 1'b0;
            `CHK(bvalid_m === 1'b0, "BVALID drops after BREADY")
        end
    endtask

    // order 0: AW and W together; 1: AW first; 2: W first
    task wr(input [7:0] a, input [31:0] d, input [3:0] s,
            input integer order, input integer bdly, input [1:0] er);
        begin
            if (order == 1) begin
                send_aw(a);
                `CHK(!awready_m, "AWREADY low while an address is held")
                `CHK(wready_m, "WREADY high while only the address is held")
                `CHK(!bvalid_m, "no BVALID with only the address")
                tick;
                `CHK(!bvalid_m, "no BVALID with only the address (gap)")
                send_w(d, s);
            end else if (order == 2) begin
                send_w(d, s);
                `CHK(!wready_m, "WREADY low while data is held")
                `CHK(awready_m, "AWREADY high while only the data is held")
                `CHK(!bvalid_m, "no BVALID with only the data")
                tick;
                `CHK(!bvalid_m, "no BVALID with only the data (gap)")
                send_aw(a);
            end else begin
                send_both(a, d, s);
            end
            wr_edge = cycle;
            finish_b(a, er, bdly);
        end
    endtask

    task wrq(input [7:0] a, input [31:0] d, input [3:0] s, input [1:0] er);
        begin
            wr(a, d, s, 0, 0, er);
        end
    endtask

    task rd(input [7:0] a, input integer rdly);
        reg     ok;
        integer i;
        begin
            araddr  = a;
            arvalid = 1'b1;
            while (arvalid) begin
                ok = arready_m;
                tick;
                if (ok) arvalid = 1'b0;
            end
            rd_edge = cycle;
            `CHK(rvalid_m === 1'b1, "RVALID high after the address is accepted")
            `CHK(!arready_m, "ARREADY low while RVALID waits")
            rd_data = rdata_m;
            rd_resp = rresp_m;
            for (i = 0; i < rdly; i = i + 1) begin
                tick;
                `CHK(rvalid_m === 1'b1, "RVALID held under backpressure")
                `CHK_EQ(rdata_m, rd_data, "RDATA stable under backpressure")
                `CHK_EQ(rresp_m, rd_resp, "RRESP stable under backpressure")
            end
            rready = 1'b1;
            tick;
            rready = 1'b0;
            `CHK(rvalid_m === 1'b0, "RVALID drops after RREADY")
        end
    endtask

    task rd_chk(input [7:0] a, input [31:0] ed, input [1:0] er);
        begin
            rd(a, 0);
            if ((rd_data === ed) && (rd_resp === er)) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("FAIL: read 0x%0h: got 0x%0h/%b expected 0x%0h/%b",
                       a, rd_data, rd_resp, ed, er);
            end
        end
    endtask

    task wait_rise(input integer prev, input integer timeout);
        integer i;
        begin
            i = 0;
            while ((irq_rises == prev) && (i < timeout)) begin
                tick;
                i = i + 1;
            end
            `CHK(irq_rises == prev + 1, "irq rose exactly once")
        end
    endtask

    task do_reset(input integer n);
        begin
            aresetn = 1'b0;
            ticks(n);
            aresetn = 1'b1;
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};

        do_reset(4);
        tick;

        // =========================== ADDR_WIDTH 8 lane ===================
        sel = 1'b1;
        tick;
        rd_chk(A_CTRL,   32'd0, OKAY);
        rd_chk(A_LOAD,   32'd0, OKAY);
        rd_chk(A_COUNT,  32'd0, OKAY);
        rd_chk(A_STATUS, 32'd0, OKAY);
        `CHK(!irq_m, "aw8: irq low after reset")

        wr(A_LOAD, 32'hA5A5A5A5, 4'hF, 0, 0, OKAY);
        wr(8'h14, 32'h11111111, 4'hF, 0, 0, SLVERR);
        wr(8'h10, 32'h00000007, 4'hF, 1, 0, SLVERR);
        wr(8'h1C, 32'h00000001, 4'hF, 2, 1, SLVERR);
        wr(8'h18, 32'h00000055, 4'hF, 0, 0, SLVERR);
        wr(8'hF4, 32'hFFFFFFFF, 4'hF, 0, 2, SLVERR);
        wr(8'h44, 32'h00000000, 4'hF, 0, 0, SLVERR);
        wr(8'h81, 32'h00000007, 4'hF, 0, 0, SLVERR);
        rd_chk(A_LOAD,   32'hA5A5A5A5, OKAY);
        rd_chk(A_CTRL,   32'd0, OKAY);
        rd_chk(A_STATUS, 32'd0, OKAY);
        rd_chk(A_COUNT,  32'd0, OKAY);
        rd_chk(8'h10, 32'd0, SLVERR);
        rd_chk(8'h14, 32'd0, SLVERR);
        rd_chk(8'h18, 32'd0, SLVERR);
        rd_chk(8'h1C, 32'd0, SLVERR);
        rd_chk(8'h84, 32'd0, SLVERR);
        rd_chk(8'hF8, 32'd0, SLVERR);
        rd_chk(8'hFC, 32'd0, SLVERR);
        rd_chk(8'h05, 32'd0, SLVERR);
        `CHK(!irq_m, "aw8: no interrupt from unmapped writes")

        // one-shot at ADDR_WIDTH 8
        wrq(A_LOAD, 32'd4, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        e0 = wr_edge;
        wait_rise(before, 20);
        `CHK_EQ(irq_rise_cycle, e0 + 4, "aw8: one-shot LOAD 4 ends on E+4")
        rd_chk(A_CTRL,   32'h2, OKAY);
        rd_chk(A_STATUS, 32'h1, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        `CHK(!irq_m, "aw8: irq low after clear")
        wrq(A_CTRL, 32'h0, 4'hF, OKAY);

        // =========================== ADDR_WIDTH 4 lane ===================
        sel = 1'b0;
        tick;
        rd_chk(A_CTRL,   32'd0, OKAY);
        rd_chk(A_LOAD,   32'd0, OKAY);
        rd_chk(A_COUNT,  32'd0, OKAY);
        rd_chk(A_STATUS, 32'd0, OKAY);
        `CHK(!irq_m, "aw4: irq low after reset")

        // LOAD with partial strobes, all channel orders, B backpressure
        wr(A_LOAD, 32'hFFFFFFFF, 4'hF, 0, 0, OKAY);
        rd_chk(A_LOAD, 32'hFFFFFFFF, OKAY);
        wr(A_LOAD, 32'h12345678, 4'b0101, 1, 2, OKAY);
        rd_chk(A_LOAD, 32'hFF34FF78, OKAY);
        wr(A_LOAD, 32'hAABBCCDD, 4'b1010, 2, 3, OKAY);
        rd_chk(A_LOAD, 32'hAA34CC78, OKAY);
        wr(A_LOAD, 32'h00000000, 4'b0000, 0, 0, OKAY);
        rd_chk(A_LOAD, 32'hAA34CC78, OKAY);
        rd(A_LOAD, 3);
        `CHK_EQ(rd_data, 32'hAA34CC78, "LOAD read with R backpressure")
        `CHK_EQ(rd_resp, OKAY, "LOAD read response")

        // CTRL write without wstrb[0]
        wr(A_CTRL, 32'h00000007, 4'b1110, 0, 0, OKAY);
        rd_chk(A_CTRL,  32'd0, OKAY);
        rd_chk(A_COUNT, 32'd0, OKAY);
        `CHK(!irq_m, "CTRL write without wstrb[0] has no effect")

        // COUNT read only; unaligned addresses
        wr(A_COUNT, 32'h00000055, 4'hF, 0, 1, SLVERR);
        rd_chk(A_COUNT, 32'd0, OKAY);
        wr(8'h01, 32'h00000007, 4'hF, 0, 0, SLVERR);
        wr(8'h06, 32'h00000000, 4'hF, 1, 0, SLVERR);
        wr(8'h0D, 32'h00000001, 4'hF, 2, 0, SLVERR);
        wr(8'h03, 32'hFFFFFFFF, 4'hF, 0, 0, SLVERR);
        rd_chk(A_LOAD,   32'hAA34CC78, OKAY);
        rd_chk(A_CTRL,   32'd0, OKAY);
        rd_chk(A_STATUS, 32'd0, OKAY);
        rd_chk(8'h02, 32'd0, SLVERR);
        rd_chk(8'h07, 32'd0, SLVERR);
        rd_chk(8'h09, 32'd0, SLVERR);
        rd_chk(8'h0F, 32'd0, SLVERR);

        // One-shot LOAD 10, timed to the cycle
        wrq(A_LOAD, 32'd10, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        e0 = wr_edge;
        rd(A_COUNT, 0);
        `CHK_EQ(rd_data, 10 - (rd_edge - 1 - e0), "COUNT value during a one-shot count")
        wait_rise(before, 30);
        `CHK_EQ(irq_rise_cycle, e0 + 10, "one-shot LOAD 10 ends on E+10")
        `CHK(irq_m, "irq high after one-shot expiry")
        rd_chk(A_CTRL,   32'h2, OKAY);
        rd_chk(A_COUNT,  32'd0, OKAY);
        rd_chk(A_STATUS, 32'h1, OKAY);
        wrq(A_STATUS, 32'h0, 4'hF, OKAY);
        rd_chk(A_STATUS, 32'h1, OKAY);
        wrq(A_STATUS, 32'h1, 4'b1110, OKAY);
        rd_chk(A_STATUS, 32'h1, OKAY);
        `CHK(irq_m, "irq still high after non-clearing STATUS writes")
        wrq(A_STATUS, 32'h1, 4'b0001, OKAY);
        `CHK(!irq_m, "irq low after STATUS clear")
        rd_chk(A_STATUS, 32'h0, OKAY);
        ticks(40);
        `CHK(irq_rises == before + 1, "one-shot: no second interrupt")
        `CHK(!irq_m, "one-shot: irq stays low")
        rd_chk(A_COUNT, 32'd0, OKAY);
        rd_chk(A_CTRL,  32'h2, OKAY);

        // One-shot LOAD 0 and LOAD 1: one-cycle counts
        wrq(A_LOAD, 32'd0, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        e0 = wr_edge;
        wait_rise(before, 10);
        `CHK_EQ(irq_rise_cycle, e0 + 1, "one-shot LOAD 0 ends on E+1")
        rd_chk(A_CTRL,  32'h2, OKAY);
        rd_chk(A_COUNT, 32'd0, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);

        wrq(A_LOAD, 32'd1, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        e0 = wr_edge;
        wait_rise(before, 10);
        `CHK_EQ(irq_rise_cycle, e0 + 1, "one-shot LOAD 1 ends on E+1")
        rd_chk(A_CTRL, 32'h2, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        `CHK(!irq_m, "irq low after clear (LOAD 1)")

        // Interrupt enable on a pending expiry
        wrq(A_LOAD, 32'd5, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h1, 4'hF, OKAY);
        ticks(12);
        `CHK(!irq_m, "irq low with IE 0")
        `CHK(irq_rises == before, "no irq rise with IE 0")
        rd_chk(A_STATUS, 32'h1, OKAY);
        rd_chk(A_CTRL,   32'h0, OKAY);
        wrq(A_CTRL, 32'h2, 4'hF, OKAY);
        `CHK(irq_rises == before + 1, "irq rises when IE set on pending expiry")
        `CHK_EQ(irq_rise_cycle, wr_edge, "irq rises on the IE write edge")
        `CHK(irq_m, "irq high with IE 1 and EXPIRED")
        wrq(A_CTRL, 32'h0, 4'hF, OKAY);
        `CHK(!irq_m, "irq low when IE written 0")
        rd_chk(A_STATUS, 32'h1, OKAY);
        wrq(A_CTRL, 32'h2, 4'hF, OKAY);
        `CHK(irq_m, "irq high again when IE written 1")
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        `CHK(!irq_m, "irq low after clear (IE test)")
        wrq(A_CTRL, 32'h0, 4'hF, OKAY);

        // Periodic LOAD 20 over several periods; clear on a count end
        wrq(A_LOAD, 32'd20, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h7, 4'hF, OKAY);
        e0 = wr_edge;
        wait_rise(before, 40);
        `CHK_EQ(irq_rise_cycle, e0 + 20, "periodic: first end on E+20")
        rd_chk(A_CTRL, 32'h7, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        `CHK(!irq_m, "periodic: irq low after clear 1")
        wait_rise(before + 1, 40);
        `CHK_EQ(irq_rise_cycle, e0 + 40, "periodic: second end on E+40")
        wait_until(e0 + 59);
        `CHK(cycle == e0 + 59, "periodic: positioned before the third end")
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        `CHK_EQ(wr_edge, e0 + 60, "periodic: clear lands on the third count end")
        `CHK(irq_m, "count end beats a clear: irq stays high")
        `CHK(irq_rises == before + 2, "count end beats a clear: no irq drop")
        rd_chk(A_STATUS, 32'h1, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        `CHK(!irq_m, "periodic: irq low after clear 3")
        wait_rise(before + 2, 40);
        `CHK_EQ(irq_rise_cycle, e0 + 80, "periodic: fourth end on E+80")
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        rd(A_COUNT, 0);
        `CHK_EQ(rd_data, 20 - (rd_edge - 1 - (e0 + 80)), "periodic: COUNT after reload")

        // Stop freezes COUNT
        wrq(A_CTRL, 32'h2, 4'hF, OKAY);
        s0 = wr_edge;
        rd(A_COUNT, 0);
        c1 = rd_data;
        `CHK_EQ(c1, 20 - (s0 - (e0 + 80)), "stop: COUNT value at the stop edge")
        ticks(30);
        rd_chk(A_COUNT, c1, OKAY);
        rd_chk(A_CTRL, 32'h2, OKAY);
        `CHK(irq_rises == before + 3, "stop: no further count ends")
        `CHK(!irq_m, "stop: irq low")
        wr(A_COUNT, 32'h00001234, 4'hF, 0, 0, SLVERR);
        rd_chk(A_COUNT, c1, OKAY);

        // Restart from stopped
        wrq(A_LOAD, 32'd8, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        r0 = wr_edge;
        wait_rise(before, 20);
        `CHK_EQ(irq_rise_cycle, r0 + 8, "restart after stop ends on R+8")
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);

        // Restart while running
        wrq(A_LOAD, 32'd30, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        ticks(10);
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        r0 = wr_edge;
        wait_rise(before, 60);
        `CHK_EQ(irq_rise_cycle, r0 + 30, "restart while running ends on R+30")
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);

        // Stop landing on a periodic count end: EN 0 wins, EXPIRED set
        wrq(A_LOAD, 32'd10, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h7, 4'hF, OKAY);
        e0 = wr_edge;
        wait_until(e0 + 9);
        wrq(A_CTRL, 32'h6, 4'hF, OKAY);
        `CHK_EQ(wr_edge, e0 + 10, "stop write lands on the count end")
        `CHK(irq_rises == before + 1, "stop on count end: expiry still set")
        `CHK_EQ(irq_rise_cycle, e0 + 10, "stop on count end: irq on E+10")
        rd_chk(A_CTRL,  32'h6, OKAY);
        rd_chk(A_COUNT, 32'd10, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        ticks(30);
        `CHK(irq_rises == before + 1, "stop on count end: no further ends")
        rd_chk(A_COUNT, 32'd10, OKAY);

        // Restart landing on a one-shot count end: EN 1 wins
        wrq(A_LOAD, 32'd10, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        e0 = wr_edge;
        wait_until(e0 + 9);
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        `CHK_EQ(wr_edge, e0 + 10, "restart write lands on the count end")
        `CHK_EQ(irq_rise_cycle, e0 + 10, "restart on count end: irq on E+10")
        rd_chk(A_CTRL, 32'h3, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        `CHK(!irq_m, "restart on count end: cleared")
        wait_rise(before + 1, 30);
        `CHK_EQ(irq_rise_cycle, e0 + 20, "restart on count end: next end on E+20")
        rd_chk(A_CTRL, 32'h2, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);

        // Periodic with LOAD 0: period 1, EN stays 1
        wrq(A_LOAD, 32'd0, 4'hF, OKAY);
        wrq(A_CTRL, 32'h5, 4'hF, OKAY);
        ticks(3);
        rd_chk(A_CTRL,   32'h5, OKAY);
        rd_chk(A_COUNT,  32'd0, OKAY);
        rd_chk(A_STATUS, 32'h1, OKAY);
        wrq(A_CTRL, 32'h0, 4'hF, OKAY);
        wrq(A_STATUS, 32'h1, 4'h1, OKAY);
        rd_chk(A_STATUS, 32'h0, OKAY);

        // Reset during a count, with a pending expiry
        wrq(A_LOAD, 32'd3, 4'hF, OKAY);
        before = irq_rises;
        wrq(A_CTRL, 32'h3, 4'hF, OKAY);
        wait_rise(before, 20);
        `CHK(irq_m, "pre-reset: expiry pending")
        wrq(A_LOAD, 32'd100, 4'hF, OKAY);
        wrq(A_CTRL, 32'h7, 4'hF, OKAY);
        ticks(10);
        do_reset(2);
        `CHK(!irq_m, "reset: irq low")
        rd_chk(A_CTRL,   32'd0, OKAY);
        rd_chk(A_LOAD,   32'd0, OKAY);
        rd_chk(A_COUNT,  32'd0, OKAY);
        rd_chk(A_STATUS, 32'd0, OKAY);
        before = irq_rises;
        ticks(120);
        `CHK(irq_rises == before, "reset: count stopped")
        rd_chk(A_COUNT, 32'd0, OKAY);

        // Reset drops a waiting BVALID
        send_both(A_LOAD, 32'h00000099, 4'hF);
        `CHK(bvalid_m === 1'b1, "BVALID waiting before reset")
        do_reset(1);
        `CHK(bvalid_m === 1'b0, "reset drops BVALID")
        `CHK(awready_m && wready_m, "write channels ready after reset")
        rd_chk(A_LOAD, 32'd0, OKAY);

        // Reset drops a waiting RVALID
        araddr  = A_LOAD;
        arvalid = 1'b1;
        `CHK(arready_m, "ARREADY high before read")
        tick;
        arvalid = 1'b0;
        `CHK(rvalid_m === 1'b1, "RVALID waiting before reset")
        do_reset(1);
        `CHK(rvalid_m === 1'b0, "reset drops RVALID")
        `CHK(arready_m, "ARREADY high after reset")

        // Reset clears a held write address
        send_aw(A_LOAD);
        `CHK(!awready_m, "address held before reset")
        do_reset(1);
        `CHK(awready_m, "reset clears the held address")
        send_w(32'h00000055, 4'hF);
        ticks(3);
        `CHK(bvalid_m === 1'b0, "no write from a held address cleared by reset")
        send_aw(A_LOAD);
        wr_edge = cycle;
        finish_b(A_LOAD, OKAY, 0);
        rd_chk(A_LOAD, 32'h00000055, OKAY);

        ticks(2);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`undef CHK
`undef CHK_EQ
=== END FILE ===
